export interface BriefView {
  id: number;
  event: BriefEvent;
  research: CompanyResearch[];
  /** Part K: open Next time I see points for people in the meeting, shown at the top of the agenda */
  talkingPoints?: TalkingPoint[];
  /**
     * Part K: the follow-up task drafted from this meeting's Granola notes
     * @nullable
     */
  followUpTaskId?: number | null;
  /** Part S: the pulse of each client organisation in an external meeting */
  pulse?: BriefViewPulseItem[];
  /**
     * Part K: when Ollie first opened this prep page
     * @nullable
     */
  openedAt?: string | null;
  generatedAt: string;
  /** The model could not write the brief. Refresh to try again. */
  failed: boolean;
  /** Nothing citable on file. Show attendees and promises only. */
  notMuch: boolean;
  /**
     * e.g. "Built from 4 emails
     * @nullable
     */
  sourcesLine: string | null;
  /** @nullable */
  why: BriefLine[] | null;
  /** @nullable */
  questions: BriefLine[] | null;
  /** @nullable */
  questionsNote: string | null;
  /**
     * Suggested agenda. Null when not much is on file or the brief was written before agendas existed.
     * @nullable
     */
  agenda: BriefLine[] | null;
  attendees: BriefAttendee[];
  promises: BriefPromise[];
  /** Open tasks for people on the meeting, promises aside */
  tasks: BriefViewTasksItem[];
  /** What Ollie is waiting on from people on the meeting */
  waitingOn: BriefViewWaitingOnItem[];
  /** Granola notes from earlier meetings with any of the same people, newest first */
  earlier: BriefViewEarlierItem[];
  /** Recent email and Slack exchanges with people on the meeting */
  threads: BriefViewThreadsItem[];
  projects: BriefViewProjectsItem[];
  goals: BriefViewGoalsItem[];
  documents: BriefViewDocumentsItem[];
  rules: BriefViewRulesItem[];
  /** Products linked to the meeting's projects and organisations, with the rules linked to each */
  products?: BriefViewProductsItem[];
  /** In use playbooks linked to the meeting's projects and organisations */
  playbooks?: BriefViewPlaybooksItem[];
  /** Attendees */
  heldBack: number;
  /**
     * Ollie's notes for after the meeting
     * @nullable
     */
  notes: string | null;
  /** @nullable */
  granolaNotes: string | null;
  /** @nullable */
  granolaRef: string | null;
  /** Granola actions that went to the Inbox */
  actions: BriefViewActionsItem[];
}

